head.script:



scwin.init = function(){
	var jsonData=[{"col1":"1"},{"col1":"2"},{"col1":"1"},{"col1":"1"},{"col1":"2"}
	,{"col1":"1"},{"col1":"2"},{"col1":"1"},{"col1":"1"},{"col1":"2"}
	,{"col1":"1"},{"col1":"2"},{"col1":"1"},{"col1":"1"},{"col1":"2"}
	,{"col1":"1"},{"col1":"2"},{"col1":"1"},{"col1":"1"},{"col1":"2"}
	,{"col1":"1"},{"col1":"2"},{"col1":"1"},{"col1":"1"},{"col1":"2"}];
	dataList1.setJSON(jsonData);


	$p.data.setBroadcast(false);
	for(var i=0; i<gridView1.getRowCount(); i++){
		var col1Data = dataList1.getCellData(i, "col1");
		var obj = {};
		if(col1Data == 1){
			obj = {
				inputType : "calendar",
				options : {
					viewType : "icon",
					calendarValueType : "yearMonth"
					,displayFormat : "yyyy"
					,dataType : "date"
				}
			}
		}else{
			obj = {
				inputType : "link",
				options : {
					displayFormatter: "scwin.getUserCsNo"
				}
			}
		}
		gridView1.setCellInputType( i , "col2" , obj );

	}

	$p.data.setBroadcast(true);
};

scwin.getUserCsNo = function(a,b,c,d){
	//debugger;
	return "formatter"+a;
}

scwin.gridView1_onviewchange = function(info) {
	if(gridView1.getColumnID(info.colIndex) == "col1"){
		if(info.newValue == 1){
			var obj = {
				inputType : "calendar",
				options : {
					viewType : "icon",
					calendarValueType : "yearMonth"
				}
			}
		}else{
			var obj = {
				inputType : "calendar",
				options : {
					viewType : "icon",
					calendarValueType : "yearMonthDate"
				}
			}
		}

	}
	gridView1.setCellInputType( info.rowIndex , "col2" , obj );
};



scwin.onpageload = function() {
	scwin.init();
};

scwin.onpageunload = function() {

};


scwin.button1_onclick = function(e) {
	grp1.show("");
};

scwin.checkVal1 = function() {
	return !WebSquare.wUnit.getDomById("gridView1_dynamic_calendar_0_1").classList.contains("br");
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
	WebSquare.wUnit.addCommand("pause", "400");				
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "500");

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
